import fs from "node:fs";
const state = JSON.parse(fs.readFileSync("e2e/.auth.json", "utf8"));
const cookie = state.cookies.map(c => `${c.name}=${c.value}`).join("; ");
const paths = process.argv.slice(2);
for (const p of paths) {
  const times = [];
  for (let i = 0; i < 4; i++) {
    const t = performance.now();
    const r = await fetch("http://localhost:3000" + p, { headers: { cookie }, redirect: "manual" });
    const reader = r.body.getReader(); let first = 0, n = 0;
    for (;;) { const { done, value } = await reader.read(); if (!first) first = performance.now() - t; if (done) break; n += value.length; }
    times.push(`${r.status} ttfb ${first.toFixed(0)} total ${(performance.now() - t).toFixed(0)}ms ${(n/1024).toFixed(0)}KB`);
  }
  console.log(p, "\n  " + times.join("\n  "));
}
EOF
