import { createClient } from "@supabase/supabase-js";
const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false } });
const email = process.env.E2E_USER_EMAIL;
const { data: users } = await db.auth.admin.listUsers({ perPage: 1000 });
const user = users.users.find(u => u.email === email);
const { data: ws } = await db.from("workspaces").select("id").eq("owner_id", user.id).single();
const w = ws.id;
const html = `<!doctype html><html><head><script src="https://cdn.jsdelivr.net/npm/echarts@5/dist/echarts.min.js"></script></head><body><div id="c" style="height:300px"></div><script>echarts.init(document.getElementById('c')).setOption({xAxis:{type:'category',data:['a','b']},yAxis:{},series:[{type:'bar',data:[1,2]}]});</script></body></html>`;
const queries = [{ name: "flow", source: "cashflow", input: { from: "2026-01-01", to: "2026-10-28", currencyCode: "EUR" } }, { name: "bal", source: "balances", input: {} }, { name: "tx", source: "transactions", input: { limit: 50 } }];
const ids = [];
for (const title of ["Seed artifact A", "Seed artifact B"]) {
  const { data: a, error } = await db.from("artifacts").insert({ workspace_id: w, title }).select("id").single(); if (error) throw error;
  const v = await db.from("artifact_versions").insert({ workspace_id: w, artifact_id: a.id, version: 1, prompt: "seed", html, queries }); if (v.error) throw v.error;
  ids.push(a.id);
}
const { data: layout } = await db.from("dashboard_layouts").select("items, version").eq("workspace_id", w).maybeSingle();
const items = [...ids.map(id => `artifact:${id}`), ...(layout?.items ?? ["balance", "spending", "recent"])];
const up = layout ? await db.from("dashboard_layouts").update({ items, version: layout.version + 1 }).eq("workspace_id", w) : await db.from("dashboard_layouts").insert({ workspace_id: w, items });
if (up.error) throw up.error;
const { data: conv, error: ce } = await db.from("conversations").insert({ workspace_id: w, title: "Seed chat" }).select("id").single(); if (ce) throw ce;
const msgs = Array.from({ length: 40 }, (_, i) => ({ workspace_id: w, conversation_id: conv.id, role: i % 2 ? "assistant" : "user", content: (i % 2 ? "Answer " : "Question ") + i + " " + "lorem ipsum ".repeat(60), created_at: new Date(Date.now() - (40 - i) * 60000).toISOString() }));
const m = await db.from("messages").insert(msgs); if (m.error) throw m.error;
console.log(JSON.stringify({ w, ids, conv: conv.id }));
EOF
