import { chromium } from "@playwright/test";
const browser = await chromium.launch();
const ctx = await browser.newContext({ storageState: "e2e/.auth.json" });
const page = await ctx.newPage();
const t0 = Date.now(); const log = [];
page.on("requestfinished", r => { const u = r.url(); if (/frame|jsdelivr|api\/conversations|_next\/static\/chunks/.test(u)) log.push(`${Date.now() - t0}ms ${u.replace("http://localhost:3000", "").slice(0, 90)}`); });
const target = process.argv[2];
await page.goto("http://localhost:3000" + target, { waitUntil: "load" });
log.push(`${Date.now() - t0}ms LOAD event`);
if (target === "/") {
  await page.waitForFunction(() => [...document.querySelectorAll("iframe")].length >= 2 && [...document.querySelectorAll("iframe")].every(f => f.offsetHeight > 0), null, { timeout: 30000 });
  log.push(`${Date.now() - t0}ms iframes present`);
}
await page.waitForTimeout(4000);
console.log(log.filter(l => !l.includes("chunks") || l.startsWith("1") === false).join("\n"));
await browser.close();
EOF
